function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 50);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(200, 400);
  brush.endShape(true);

  // Hills
  brush.fill("#87CEEB", 30);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(200, 400);
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 70);
  brush.beginShape();
  brush.vertex(150, 100);
  brush.vertex(250, 50);
  brush.vertex(100, 150);
  brush.endShape(true);
}
